import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import PaymentModal from '../components/paymentModal';
import Navbar from '../components/Navbar';
import { API_URL } from '../config';

const Catalog = () => {
  const [courses, setCourses] = useState([]);
  const [categories, setCategories] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [category, setCategory] = useState('Tous');
  const [selectedCourse, setSelectedCourse] = useState(null);

  useEffect(() => {
    fetch(`${API_URL}/courses/`)
      .then(res => {
        if (!res.ok) throw new Error('Impossible de charger les cours.');
        return res.json();
      })
      .then(data => setCourses(data))
      .catch(err => setError(err.message))
      .finally(() => setLoading(false));

    fetch(`${API_URL}/categories/`)
      .then(res => res.ok ? res.json() : [])
      .then(data => setCategories(data));
  }, []);

  const filtered = courses.filter(c =>
    (category === 'Tous' || c.category === category) &&
    c.title.toLowerCase().includes(search.toLowerCase())
  );

  return (
    <div className="relative min-h-screen bg-[#0A0E1A] text-white overflow-hidden">
      <div className="absolute inset-0 overflow-hidden pointer-events-none">
        <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[600px] h-[300px] bg-blue-600/10 blur-[120px] rounded-full"></div>
        <div className="absolute inset-0 flex items-start justify-center overflow-hidden">
          <img
            src="/logo-icon.png"
            alt=""
            className="w-[900px] md:w-[1300px] lg:w-[1600px] object-contain opacity-[0.08] select-none mt-[-100px]"
          />
        </div>
      </div>

      <div className="relative z-10">
        <Navbar />

        <section className="max-w-6xl mx-auto px-6 pt-16 pb-20">
          <h1 className="text-3xl font-bold mb-8">Catalogue des formations</h1>

          <div className="flex flex-col md:flex-row gap-4 mb-10">
            <input
              type="text"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Rechercher un module..."
              className="flex-1 bg-slate-900/80 border border-slate-700 rounded-full px-5 py-3 text-sm text-white placeholder:text-slate-500 outline-none focus:border-blue-500 transition-colors"
            />
            <div className="flex gap-2 flex-wrap">
              <button
                onClick={() => setCategory('Tous')}
                className={`px-4 py-2 rounded-full text-xs font-semibold uppercase tracking-wide border transition-colors ${
                  category === 'Tous'
                    ? 'border-blue-500 bg-blue-500/10 text-blue-400'
                    : 'border-slate-700 text-slate-400 hover:border-slate-500'
                }`}
              >
                Tous
              </button>
              {categories.map(cat => (
                <button
                  key={cat.id}
                  onClick={() => setCategory(cat.name)}
                  className={`px-4 py-2 rounded-full text-xs font-semibold uppercase tracking-wide border transition-colors ${
                    category === cat.name
                      ? 'border-blue-500 bg-blue-500/10 text-blue-400'
                      : 'border-slate-700 text-slate-400 hover:border-slate-500'
                  }`}
                >
                  {cat.name}
                </button>
              ))}
            </div>
          </div>

          {loading ? (
            <p className="text-slate-500 text-sm">Chargement des formations...</p>
          ) : error ? (
            <p className="text-red-400 text-sm">{error} — vérifie que le serveur backend tourne bien sur {API_URL}.</p>
          ) : filtered.length > 0 ? (
            <div className="grid md:grid-cols-3 gap-6">
              {filtered.map(course => (
                <div key={course.id} className="group bg-slate-900/60 border border-slate-800 rounded-2xl overflow-hidden hover:border-blue-500/40 hover:bg-slate-900 transition-all duration-300 shadow-xl flex flex-col">
                  <div className="relative h-40 overflow-hidden">
                    <img
                      src={course.thumbnail_url || 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?w=600'}
                      alt={course.title}
                      className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
                    />
                    {course.is_bestseller && (
                      <span className="absolute top-3 left-3 bg-amber-400 text-slate-900 text-[10px] font-bold uppercase tracking-wide px-2.5 py-1 rounded">
                        Meilleure vente
                      </span>
                    )}
                  </div>
                  <div className="p-6 flex flex-col justify-between flex-1">
                    <div>
                      <div className="flex items-center justify-between mb-3">
                        <span className={`text-[11px] font-bold uppercase tracking-wide px-3 py-1 rounded-full ${
                          course.is_free ? 'bg-emerald-500/10 text-emerald-400' : 'bg-blue-500/10 text-blue-400'
                        }`}>
                          {course.is_free ? 'Gratuit' : 'Premium'}
                        </span>
                        <span className="text-xs font-mono text-slate-500">
                          {course.is_free ? '0 FCFA' : `${course.price.toLocaleString()} FCFA`}
                        </span>
                      </div>
                      <h3 className="text-lg font-bold mb-1 leading-snug group-hover:text-blue-400 transition-colors">
                        {course.title}
                      </h3>
                      {course.instructor_name && (
                        <p className="text-xs text-slate-500 mb-2">Par {course.instructor_name}</p>
                      )}
                      {course.reviews_count > 0 && (
                        <div className="flex items-center gap-1.5 mb-4 text-xs">
                          <span className="text-amber-400 font-bold">{(course.rating / 10).toFixed(1)}</span>
                          <span className="text-amber-400">★★★★★</span>
                          <span className="text-slate-500">({course.reviews_count} avis)</span>
                        </div>
                      )}
                      <p className="text-slate-400 text-sm leading-relaxed mb-6">{course.description}</p>
                    </div>
                    <div className="flex gap-3">
                      <Link to={`/course/${course.id}`} className="flex-1 text-center border border-slate-700 hover:border-slate-500 text-slate-300 hover:text-white font-semibold py-3 rounded-lg text-sm transition-colors">
                        Détails
                      </Link>
                      <button onClick={() => setSelectedCourse(course)} className="flex-1 bg-blue-600 hover:bg-blue-500 text-white font-semibold py-3 rounded-lg text-sm transition-colors">
                        {course.is_free ? 'Accéder' : 'Débloquer'}
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="border border-dashed border-slate-800 rounded-2xl p-12 text-center text-slate-500 text-sm">
              Aucun cours trouvé.
            </div>
          )}
        </section>
      </div>

      {selectedCourse && <PaymentModal course={selectedCourse} onClose={() => setSelectedCourse(null)} />}
    </div>
  );
};
export default Catalog;
